queries.query:
SELECT ?film ?en ?sv ?time ?ceremony ?ceremonyLabel ?ceremonyDate ?ceremonyOrdinal ?rank WHERE {
  ?film p:P166 ?st .
  ?st ps:P166 wd:Q102427 ; wikibase:rank ?rank .
  FILTER(?rank != wikibase:DeprecatedRank)
  OPTIONAL { ?st pq:P585 ?time }
  OPTIONAL { ?st pq:P805 ?ceremony .
    OPTIONAL { ?ceremony wdt:P585 ?ceremonyDate }
    OPTIONAL { ?ceremony wdt:P1545 ?ceremonyOrdinal }
    OPTIONAL { ?ceremony rdfs:label ?ceremonyLabel FILTER(LANG(?ceremonyLabel) = "en") } }
  OPTIONAL { ?film rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?film rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
}
ORDER BY ?time

SELECT ?film ?ceremony ?ceremonyLabel ?kind ?lang ?text WHERE {
  ?film p:P166 ?st .
  ?st ps:P166 wd:Q102427 ; pq:P805 ?ceremony ; wikibase:rank ?rank .
  FILTER(?rank != wikibase:DeprecatedRank)
  ?film wdt:P31/wdt:P279* wd:Q11424 .
  ?ceremony rdfs:label ?ceremonyLabel FILTER(LANG(?ceremonyLabel) = "en")
  { ?film rdfs:label ?text . BIND("label" AS ?kind) }
  UNION { ?film skos:altLabel ?text . BIND("alias" AS ?kind) }
  BIND(LANG(?text) AS ?lang)
  FILTER(?lang IN ("en", "sv", "mul"))
}
ORDER BY ?ceremonyLabel ?lang ?kind
